insert into public.livro_habilidades(ref, sistema, fonte, classe, grupo, nome, circulo, elemento, ordem, dados) values
('op:ritual:Amaldiçoar Arma','op','livro-basico',null,'ritual','Amaldiçoar Arma',1,null,1000,'{"tipo": "ritual", "circ": 1, "el": "", "pe": 1, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 arma corpo a corpo ou pacote de munição. Duração: cena. Ao aprender, escolha o elemento (Conhecimento, Energia, Morte ou Sangue): o ritual passa a ser dele. A arma ou munição causa +1d6 de dano desse elemento. Discente +2 PE (2º círculo): +2d6. Verdadeiro +5 PE (3º círculo e afinidade): +4d6.", "ef": []}'::jsonb),
('op:ritual:Compreensão Paranormal','op','livro-basico',null,'ritual','Compreensão Paranormal',1,'Conhecimento',1001,'{"tipo": "ritual", "circ": 1, "el": "Conhecimento", "pe": 1, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 ser ou objeto. Duração: cena. Resistência: Vontade anula (veja texto). Tocando objeto com informação, você entende o idioma humano (não símbolos paranormais). Tocando pessoa, comunicam-se como se tivessem idioma comum. Tocando animal, percebe sentimentos básicos. Alvo involuntário faz Vontade. Discente +2 PE (2º círculo): alcance curto, alvos escolhidos; entende todos. Verdadeiro +5 PE (3º círculo): alcance pessoal, alvo você; fala, entende e escreve qualquer idioma humano.", "ef": []}'::jsonb),
('op:ritual:Enfeitiçar','op','livro-basico',null,'ritual','Enfeitiçar',1,'Conhecimento',1002,'{"tipo": "ritual", "circ": 1, "el": "Conhecimento", "pe": 1, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 pessoa. Duração: cena. Resistência: Vontade anula. O alvo fica prestativo (não controlado) e você tem +10 em Diplomacia com ele. Alvo hostil ou em combate: +5 no teste dele. Ação hostil sua ou de aliado dissipa o efeito. Discente +2 PE (2º círculo): em vez do normal, sugere uma ação aceitável e o alvo obedece; o efeito termina ao executar (pode dar uma condição). Verdadeiro +5 PE (3º círculo): afeta todos os alvos no alcance.", "ef": []}'::jsonb),
('op:ritual:Ouvir os Sussurros','op','livro-basico',null,'ritual','Ouvir os Sussurros',1,'Conhecimento',1003,'{"tipo": "ritual", "circ": 1, "el": "Conhecimento", "pe": 1, "desc": "Execução: completa. Alcance: pessoal. Alvo/área: você. Duração: instantânea. Faça uma pergunta de sim ou não sobre uma ação que fará na cena. O mestre rola 1d6 em segredo: 2 a 6, recebe a resposta (sim, não ou sim e não); 1, falha e a resposta é não. Repetir o ritual dá sempre o primeiro resultado. Discente +2 PE (2º círculo): execução 1 minuto; pergunta sobre evento até 1 dia à frente; 2 a 6 dá resposta ou pista. Verdadeiro +5 PE (3º círculo): execução 10 minutos, duração 5 rodadas; uma pergunta por rodada (sim, não ou ninguém sabe).", "ef": []}'::jsonb),
('op:ritual:Perturbação','op','livro-basico',null,'ritual','Perturbação',1,'Conhecimento',1004,'{"tipo": "ritual", "circ": 1, "el": "Conhecimento", "pe": 1, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 pessoa. Duração: 1 rodada. Resistência: Vontade anula. Dá uma ordem; se falhar, o alvo a cumpre no próprio turno. Escolha: Fuja (gasta o turno se afastando), Largue (solta itens, não os pega até seu próximo turno), Pare (pasmo), Sente-se (senta no chão, só levanta no próximo turno), Venha (gasta o turno se aproximando). Discente +2 PE: alvo 1 ser; comando extra Sofra: 3d8 de Conhecimento e abalado por 1 rodada. Verdadeiro +5 PE (3º círculo e afinidade): até 5 seres, ou comando Ataque: o alvo agride outro alvo à sua escolha em alcance médio.", "ef": []}'::jsonb),
('op:ritual:Tecer Ilusão','op','livro-basico',null,'ritual','Tecer Ilusão',1,'Conhecimento',1005,'{"tipo": "ritual", "circ": 1, "el": "Conhecimento", "pe": 1, "desc": "Execução: padrão. Alcance: médio. Alvo/área: ilusão em até 4 cubos de 1,5m. Duração: cena. Resistência: Vontade desacredita. Cria ilusão visual ou sonora simples (volume de voz por cubo). Sem cheiro, textura ou temperatura. Seres e objetos a atravessam sem dano. Dissipa se você sair do alcance. Discente +2 PE (2º círculo): até 8 cubos, sustentada; imagem e som combinados, sons complexos, odores e sensações; seres precisam de Vontade para atravessar; ação livre para mover ou alterar. Verdadeiro +5 PE (3º círculo): ilusão de perigo mortal: Vontade ao conjurar e a cada turno seu; falha = acredita e sofre 6d6 de Conhecimento; 2 sucessos seguidos anulam.", "ef": []}'::jsonb),
('op:ritual:Terceiro Olho','op','livro-basico',null,'ritual','Terceiro Olho',1,'Conhecimento',1006,'{"tipo": "ritual", "circ": 1, "el": "Conhecimento", "pe": 1, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: você. Duração: cena. Vê auras paranormais em alcance longo (rituais, itens amaldiçoados e criaturas), sabendo elemento e poder aproximado: fraca (1º círculo, VD até 80), moderada (2º e 3º, VD 81 a 280), poderosa (4º, VD 281+). Ação de movimento: descobre se um ser visto em alcance médio tem poderes ou conjura rituais, e de quais elementos. Discente +2 PE: duração 1 dia. Verdadeiro +5 PE: também enxerga objetos e seres invisíveis (formas translúcidas).", "ef": []}'::jsonb),
('op:ritual:Amaldiçoar Tecnologia','op','livro-basico',null,'ritual','Amaldiçoar Tecnologia',1,'Energia',1007,'{"tipo": "ritual", "circ": 1, "el": "Energia", "pe": 1, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 acessório ou arma de fogo. Duração: cena. O item funciona acima da capacidade: recebe uma modificação à sua escolha. Discente +2 PE (2º círculo): duas modificações. Verdadeiro +5 PE (3º círculo e afinidade): três modificações.", "ef": []}'::jsonb),
('op:ritual:Coincidência Forçada','op','livro-basico',null,'ritual','Coincidência Forçada',1,'Energia',1008,'{"tipo": "ritual", "circ": 1, "el": "Energia", "pe": 1, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 ser. Duração: cena. O alvo recebe +2 em testes de perícia. Discente +2 PE (2º círculo): alvo aliados à sua escolha. Verdadeiro +5 PE (3º círculo e afinidade): aliados à sua escolha e bônus +5.", "ef": []}'::jsonb),
('op:ritual:Eletrocussão','op','livro-basico',null,'ritual','Eletrocussão',1,'Energia',1009,'{"tipo": "ritual", "circ": 1, "el": "Energia", "pe": 1, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 ser ou objeto. Duração: instantânea. Resistência: Fortitude parcial. 3d6 de dano de eletricidade e vulnerável por 1 rodada; passou: metade e sem a condição. Contra objeto eletrônico: dobro do dano e ignora resistência. Discente +2 PE (2º círculo): área linha de 30m: 6d6 de Energia em todos os seres e objetos livres. Verdadeiro +5 PE (3º círculo): alvos escolhidos; um relâmpago para cada, 8d6 de Energia.", "ef": []}'::jsonb),
('op:ritual:Embaralhar','op','livro-basico',null,'ritual','Embaralhar',1,'Energia',1010,'{"tipo": "ritual", "circ": 1, "el": "Energia", "pe": 1, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: você. Duração: cena. Cria 3 cópias ilusórias: +6 na Defesa. Cada ataque que erra remove uma cópia e o bônus cai 2. O oponente precisa ver as cópias (invisível ou olhos fechados: sem bônus). Discente +2 PE (2º círculo): 5 cópias, bônus +10. Verdadeiro +5 PE (3º círculo): 8 cópias, bônus +16; cada cópia destruída emite clarão e quem a destruiu fica ofuscado por 1 rodada.", "ef": []}'::jsonb),
('op:ritual:Luz','op','livro-basico',null,'ritual','Luz',1,'Energia',1011,'{"tipo": "ritual", "circ": 1, "el": "Energia", "pe": 1, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 objeto. Duração: cena. Resistência: Vontade anula (veja texto). O objeto emite luz colorida, sem calor, num raio de 9m. Guardado, a luz para. Objeto em posse de pessoa involuntária: Vontade anula. Discente +2 PE (2º círculo): alcance longo; 4 esferas de luz (6m cada) que você move com ação livre; ser no espaço da esfera fica ofuscado. Verdadeiro +5 PE (3º círculo): luz cálida; aliados na área +1d20 em Vontade, inimigos ofuscados.", "ef": []}'::jsonb),
('op:ritual:Polarização Caótica','op','livro-basico',null,'ritual','Polarização Caótica',1,'Energia',1012,'{"tipo": "ritual", "circ": 1, "el": "Energia", "pe": 1, "desc": "Execução: padrão. Alcance: curto. Alvo/área: você. Duração: sustentada. Resistência: Vontade anula. Aura magnética. Escolha: Atrair (ação de movimento puxa objeto metálico de espaço 2 ou menor no alcance) ou Repelir (resistência 5 a balístico, corte, impacto e perfuração contra projéteis de espaço 2 ou menor). Discente +2 PE: expele a energia de uma vez e arremessa até 10 objetos (ou 10 espaços) a até 3m entre si: 1 a 1d6 de impacto por espaço (Reflexos metade); seres arremessados fazem Vontade para evitar; colisão 1d6 por 3m. Verdadeiro +5 PE: alcance médio; ação de movimento levita e move um ser ou objeto de espaço 10 ou menor por até 9m (Vontade anula).", "ef": []}'::jsonb),
('op:ritual:Cicatrização','op','livro-basico',null,'ritual','Cicatrização',1,'Morte',1013,'{"tipo": "ritual", "circ": 1, "el": "Morte", "pe": 1, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 ser. Duração: instantânea. O alvo recupera 3d8+3 PV, mas envelhece 1 ano. Discente +2 PE (2º círculo): cura 5d8+5. Verdadeiro +9 PE (4º círculo e afinidade com Morte): alcance curto, seres escolhidos, cura 7d8+7.", "ef": []}'::jsonb),
('op:ritual:Consumir Manancial','op','livro-basico',null,'ritual','Consumir Manancial',1,'Morte',1014,'{"tipo": "ritual", "circ": 1, "el": "Morte", "pe": 1, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: você. Duração: instantânea. Suga o tempo de vida ao redor e recebe 3d6 PV temporários até o fim da cena. Discente +2 PE (2º círculo): 6d6 PV temporários. Verdadeiro +5 PE (3º círculo e afinidade): área esfera de 6m de raio em você, Fortitude metade: 3d6 de Morte em cada ser vivo e você recebe PV temporários iguais ao dano total.", "ef": []}'::jsonb),
('op:ritual:Decadência','op','livro-basico',null,'ritual','Decadência',1,'Morte',1015,'{"tipo": "ritual", "circ": 1, "el": "Morte", "pe": 1, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 ser. Duração: instantânea. Resistência: Fortitude metade. O alvo sofre 2d8+2 de dano de Morte. Discente +2 PE: sem resistência, 3d8+3; você transfere as espirais a uma arma e ataca corpo a corpo: soma o dano da arma e do ritual. Verdadeiro +5 PE (3º círculo): alcance pessoal, área explosão de 6m de raio, dano 8d8+8.", "ef": []}'::jsonb),
('op:ritual:Definhar','op','livro-basico',null,'ritual','Definhar',1,'Morte',1016,'{"tipo": "ritual", "circ": 1, "el": "Morte", "pe": 1, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 ser. Duração: cena. Resistência: Fortitude parcial. O alvo fica fatigado; se passar, fica vulnerável. Discente +2 PE (2º círculo): em vez disso fica exausto (passou: fatigado). Verdadeiro +5 PE (3º círculo e afinidade): como discente, em até 5 seres.", "ef": []}'::jsonb),
('op:ritual:Espirais da Perdição','op','livro-basico',null,'ritual','Espirais da Perdição',1,'Morte',1017,'{"tipo": "ritual", "circ": 1, "el": "Morte", "pe": 1, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 ser. Duração: cena. O alvo sofre –1d20 em testes de ataque. Discente +2 PE (2º círculo): –2d20. Verdadeiro +8 PE (3º círculo): –2d20 e alvo seres escolhidos.", "ef": []}'::jsonb),
('op:ritual:Nuvem de Cinzas','op','livro-basico',null,'ritual','Nuvem de Cinzas',1,'Morte',1018,'{"tipo": "ritual", "circ": 1, "el": "Morte", "pe": 1, "desc": "Execução: padrão. Alcance: curto. Alvo/área: nuvem de 6m de raio e 6m de altura. Duração: cena. Fuligem espessa: camuflagem a até 1,5m e camuflagem total a partir de 3m. Vento forte dispersa em 4 rodadas, vendaval em 1. Não funciona sob a água. Discente +2 PE (2º círculo): você escolhe seres que enxergam através do efeito. Verdadeiro +5 PE (3º círculo): nuvem quase sólida: deslocamento 3m e –2 em ataques para quem estiver dentro.", "ef": []}'::jsonb),
('op:ritual:Arma Atroz','op','livro-basico',null,'ritual','Arma Atroz',1,'Sangue',1019,'{"tipo": "ritual", "circ": 1, "el": "Sangue", "pe": 1, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 arma corpo a corpo. Duração: sustentada. A arma fornece +2 em testes de ataque e +1 na margem de ameaça. Discente +2 PE (2º círculo): bônus de ataque +5. Verdadeiro +5 PE (3º círculo e afinidade): +5 em ataque e +2 na margem de ameaça e no multiplicador de crítico.", "ef": []}'::jsonb),
('op:ritual:Armadura de Sangue','op','livro-basico',null,'ritual','Armadura de Sangue',1,'Sangue',1020,'{"tipo": "ritual", "circ": 1, "el": "Sangue", "pe": 1, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: você. Duração: cena. +5 na Defesa, cumulativo com outros rituais mas não com bônus de equipamento. Discente +5 PE (3º círculo): +10 na Defesa e resistência 5 a balístico, corte, impacto e perfuração. Verdadeiro +9 PE (4º círculo e afinidade): +15 na Defesa e resistência 10 a esses tipos.", "ef": []}'::jsonb),
('op:ritual:Corpo Adaptado','op','livro-basico',null,'ritual','Corpo Adaptado',1,'Sangue',1021,'{"tipo": "ritual", "circ": 1, "el": "Sangue", "pe": 1, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 pessoa ou animal. Duração: cena. Imune a calor e frio extremos, respira na água (ou no ar) e não sufoca em fumaça densa. Discente +2 PE: duração 1 dia. Verdadeiro +5 PE: alcance curto, pessoas ou animais escolhidos.", "ef": []}'::jsonb),
('op:ritual:Distorcer Aparência','op','livro-basico',null,'ritual','Distorcer Aparência',1,'Sangue',1022,'{"tipo": "ritual", "circ": 1, "el": "Sangue", "pe": 1, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: você. Duração: cena. Resistência: Vontade desacredita. Muda sua aparência (altura, peso, pele, cabelo, voz, impressão digital etc.): +10 em Enganação para disfarce. Não ganha habilidades da nova forma. Discente +2 PE: alcance curto, alvo 1 ser (involuntário anula com Vontade). Verdadeiro +5 PE (3º círculo): como discente, seres escolhidos.", "ef": []}'::jsonb),
('op:ritual:Fortalecimento Sensorial','op','livro-basico',null,'ritual','Fortalecimento Sensorial',1,'Sangue',1023,'{"tipo": "ritual", "circ": 1, "el": "Sangue", "pe": 1, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: você. Duração: cena. +1d20 em Investigação, Luta, Percepção e Pontaria. Discente +2 PE (2º círculo): inimigos sofrem –1d20 em ataques contra você. Verdadeiro +5 PE (4º círculo e afinidade): imune a surpreendido e desprevenido, +10 em Defesa e Reflexos.", "ef": []}'::jsonb),
('op:ritual:Ódio Incontrolável','op','livro-basico',null,'ritual','Ódio Incontrolável',1,'Sangue',1024,'{"tipo": "ritual", "circ": 1, "el": "Sangue", "pe": 1, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 pessoa. Duração: cena. Frenesi: +2 em ataque e dano corpo a corpo e resistência 5 a balístico, corte, impacto e perfuração. Não faz ações calmas (Furtividade, rituais) e deve atacar todo turno, mesmo um aliado se for o único ao alcance. Discente +2 PE: ao usar agredir, faz um ataque corpo a corpo adicional contra o mesmo alvo. Verdadeiro +5 PE (3º círculo e afinidade): bônus +5 e o alvo sofre só metade do dano desses tipos.", "ef": []}'::jsonb),
('op:ritual:Cinerária','op','livro-basico',null,'ritual','Cinerária',1,'Medo',1025,'{"tipo": "ritual", "circ": 1, "el": "Medo", "pe": 1, "desc": "Execução: padrão. Alcance: curto. Alvo/área: nuvem de 6m de raio. Duração: cena. Névoa de essência paranormal: rituais conjurados dentro dela têm DT +5. Discente +2 PE: rituais conjurados na névoa custam –2 PE. Verdadeiro +5 PE: rituais conjurados na névoa causam dano maximizado.", "ef": []}'::jsonb),
('op:ritual:Aprimorar Mente','op','livro-basico',null,'ritual','Aprimorar Mente',2,'Conhecimento',1026,'{"tipo": "ritual", "circ": 2, "el": "Conhecimento", "pe": 3, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 ser. Duração: cena. +1 em Intelecto ou Presença à escolha do alvo (não fornece PE nem perícias treinadas). Discente +3 PE (3º círculo): +2. Verdadeiro +7 PE (4º círculo e afinidade): +3.", "ef": []}'::jsonb),
('op:ritual:Detecção de Ameaças','op','livro-basico',null,'ritual','Detecção de Ameaças',2,'Conhecimento',1027,'{"tipo": "ritual", "circ": 2, "el": "Conhecimento", "pe": 3, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: esfera de 18m de raio. Duração: cena. Quando ser hostil ou armadilha entra na área, você sente o perigo e pode, com ação de movimento, fazer Percepção (DT 20): se passar, sabe direção e distância. Discente +3 PE (3º círculo): não fica desprevenido contra perigos detectados e +5 em resistência contra armadilhas. Verdadeiro +5 PE (4º círculo): duração 1 dia, com os benefícios do discente.", "ef": []}'::jsonb),
('op:ritual:Esconder dos Olhos','op','livro-basico',null,'ritual','Esconder dos Olhos',2,'Conhecimento',1028,'{"tipo": "ritual", "circ": 2, "el": "Conhecimento", "pe": 3, "desc": "Execução: livre. Alcance: pessoal. Alvo/área: você. Duração: 1 rodada. Fica invisível (com equipamento): camuflagem total e +15 em Furtividade; quem não o vê fica desprevenido. Termina se atacar ou usar habilidade hostil. Luz carregada continua visível. Discente +3 PE (3º círculo): sustentada; esfera de invisibilidade: você e aliados a até 3m ficam invisíveis. Verdadeiro +7 PE (4º círculo e afinidade): execução padrão, toque, 1 ser, sustentada; ação hostil não dissipa.", "ef": []}'::jsonb),
('op:ritual:Invadir Mente','op','livro-basico',null,'ritual','Invadir Mente',2,'Conhecimento',1029,'{"tipo": "ritual", "circ": 2, "el": "Conhecimento", "pe": 3, "desc": "Execução: padrão. Alcance: médio ou toque. Alvo/área: 1 ser ou 2 pessoas voluntárias. Duração: instantânea ou 1 dia. Resistência: Vontade parcial ou nenhuma. Escolha: Rajada Mental (6d6 de Conhecimento e atordoado por 1 rodada; passou: metade e sem atordoar; atordoa 1 vez por cena) ou Ligação Telepática (elo mental entre duas pessoas, 1 dia). Discente +3 PE (3º círculo): rajada 10d6; ou ligação em que você usa ação de movimento para ver e ouvir pelo alvo (involuntário suprime 1h com Vontade). Verdadeiro +7 PE (4º círculo): rajada 10d6 em seres escolhidos; ou ligação entre até 5 pessoas.", "ef": []}'::jsonb),
('op:ritual:Localização','op','livro-basico',null,'ritual','Localização',2,'Conhecimento',1030,'{"tipo": "ritual", "circ": 2, "el": "Conhecimento", "pe": 3, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: círculo de 90m de raio. Duração: cena. Encontra pessoa ou objeto (geral ou específico): indica direção e distância do mais próximo. Algo muito específico exige imagem precisa; falha gasta os PE. Chumbo fino bloqueia. Discente +3 PE: alcance toque, 1 pessoa, 1 hora: descobre o caminho mais direto para entrar ou sair de um lugar. Verdadeiro +7 PE (4º círculo): área de 1 km de raio.", "ef": []}'::jsonb),
('op:ritual:Chamas do Caos','op','livro-basico',null,'ritual','Chamas do Caos',2,'Energia',1031,'{"tipo": "ritual", "circ": 2, "el": "Energia", "pe": 3, "desc": "Execução: padrão. Alcance: curto. Alvo/área: veja texto. Duração: cena. Escolha: Chamejar (arma corpo a corpo +1d6 de fogo), Esquentar (objeto sofre 1d6 de fogo por rodada e passa o dano a quem o segura; ação completa para resfriar), Extinguir (apaga chama Grande ou menor; fumaça de 3m dá camuflagem), Modelar (move chama 9m por rodada com ação livre; 3d6 de fogo em ser atravessado, uma vez por rodada). Discente +3 PE: sustentada, Reflexos metade; 1x por rodada, ação de movimento para labareda em alvo no alcance curto: 4d6 de Energia. Verdadeiro +7 PE (3º círculo): como discente com 8d6.", "ef": []}'::jsonb),
('op:ritual:Contenção Fantasmagórica','op','livro-basico',null,'ritual','Contenção Fantasmagórica',2,'Energia',1032,'{"tipo": "ritual", "circ": 2, "el": "Energia", "pe": 3, "desc": "Execução: padrão. Alcance: médio. Alvo/área: 1 ser. Duração: cena. Resistência: Reflexos anula. Três laços de Energia agarram o alvo. Ele pode gastar ação padrão e Atletismo (DT do ritual) para destruir um laço (mais um por 5 acima da DT). Laços: Defesa 10, 10 PV, RD 5, imunes a Energia; afetam incorpóreos. Discente +3 PE (3º círculo): 6 laços; você escolhe o alvo de cada um (mínimo 2 por alvo). Verdadeiro +5 PE (3º círculo e afinidade): como discente; cada laço destruído causa 2d6+2 de Energia no alvo agarrado.", "ef": []}'::jsonb),
('op:ritual:Dissonância Acústica','op','livro-basico',null,'ritual','Dissonância Acústica',2,'Energia',1033,'{"tipo": "ritual", "circ": 2, "el": "Energia", "pe": 3, "desc": "Execução: padrão. Alcance: médio. Alvo/área: esfera de 6m de raio. Duração: sustentada. Todos na área ficam surdos e não conseguem conjurar rituais. Discente +1 PE: alvo 1 objeto, que emana silêncio de 3m (objeto de involuntário: Vontade anula). Verdadeiro +3 PE (3º círculo): duração cena; nenhum som sai da área, mas quem está dentro fala, ouve e conjura normalmente.", "ef": []}'::jsonb),
('op:ritual:Sopro do Caos','op','livro-basico',null,'ritual','Sopro do Caos',2,'Energia',1034,'{"tipo": "ritual", "circ": 2, "el": "Energia", "pe": 3, "desc": "Execução: padrão. Alcance: médio. Alvo/área: área varia. Duração: sustentada. Resistência: veja texto. Escolha: Ascender (ergue ser ou objeto Médio até 30m, 6m por rodada com ação de movimento; vulnerável; involuntário faz Fortitude no início dos turnos), Sopro (cone de 4,5m: empurrar com Ocultismo em alvos Médios ou menores; manter exige ação padrão) ou Vento (área de vento forte; manter exige ação de movimento). Discente +3 PE: afeta alvos Grandes. Verdadeiro +9 PE: afeta alvos Enormes.", "ef": []}'::jsonb),
('op:ritual:Tela de Ruído','op','livro-basico',null,'ritual','Tela de Ruído',2,'Energia',1035,'{"tipo": "ritual", "circ": 2, "el": "Energia", "pe": 3, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: você. Duração: cena. Película que dá 30 PV temporários apenas contra dano balístico, de corte, de impacto ou de perfuração. Alternativa: como reação ao sofrer dano, resistência 15 só contra esse dano. Discente +3 PE: 60 PV temporários / resistência 30. Verdadeiro +7 PE (4º círculo): alcance curto, 1 ser ou objeto Enorme ou menor: esfera imóvel que nada atravessa (Reflexos evita ser aprisionado).", "ef": []}'::jsonb),
('op:ritual:Desacelerar Impacto','op','livro-basico',null,'ritual','Desacelerar Impacto',2,'Morte',1036,'{"tipo": "ritual", "circ": 2, "el": "Morte", "pe": 3, "desc": "Execução: reação. Alcance: curto. Alvo/área: 1 ser ou objetos até 10 espaços. Duração: até chegar ao solo ou cena. O alvo cai a 18m por rodada (sem dano). Projétil causa metade do dano. Só funciona em queda livre. Discente +3 PE: até 100 espaços.", "ef": []}'::jsonb),
('op:ritual:Eco Espiral','op','livro-basico',null,'ritual','Eco Espiral',2,'Morte',1037,'{"tipo": "ritual", "circ": 2, "el": "Morte", "pe": 3, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 ser. Duração: 2 rodadas. Resistência: Fortitude metade. Cópia de cinzas do alvo. No turno seguinte, ação padrão para se concentrar; no segundo turno, ação padrão para descarregar: o alvo sofre dano de Morte igual ao dano que sofreu na rodada de concentração (Fortitude metade). Discente +3 PE: até 5 seres. Verdadeiro +7 PE (4º círculo e afinidade): até 3 rodadas (concentra nas duas primeiras, descarrega na terceira).", "ef": []}'::jsonb),
('op:ritual:Miasma Entrópico','op','livro-basico',null,'ritual','Miasma Entrópico',2,'Morte',1038,'{"tipo": "ritual", "circ": 2, "el": "Morte", "pe": 3, "desc": "Execução: padrão. Alcance: médio. Alvo/área: nuvem de 6m de raio. Duração: instantânea. Resistência: Fortitude parcial (veja texto). 4d8 de dano químico e enjoado por 1 rodada; passou: metade e sem enjoo. Discente +3 PE: 6d8 de Morte. Verdadeiro +7 PE (3º círculo): duração 3 rodadas; quem inicia o turno na área sofre o dano de novo.", "ef": []}'::jsonb),
('op:ritual:Paradoxo','op','livro-basico',null,'ritual','Paradoxo',2,'Morte',1039,'{"tipo": "ritual", "circ": 2, "el": "Morte", "pe": 3, "desc": "Execução: padrão. Alcance: médio. Alvo/área: esfera de 6m de raio. Duração: instantânea. Resistência: Fortitude metade. 6d6 de Morte em todos os seres da área. Discente +3 PE: efeito esfera Média (1,5m) por cena: 4d6 de Morte a quem estiver no mesmo espaço; ação de movimento move 9m; cada ser sofre 1x por rodada. Verdadeiro +7 PE (4º círculo): 13d6; quem chegar a 0 PV faz Fortitude: falha = reduzido a cinzas (morre).", "ef": []}'::jsonb),
('op:ritual:Velocidade Mortal','op','livro-basico',null,'ritual','Velocidade Mortal',2,'Morte',1040,'{"tipo": "ritual", "circ": 2, "el": "Morte", "pe": 3, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 ser. Duração: sustentada. O alvo ganha uma ação de movimento adicional por turno (não pode conjurar rituais com ela). Discente +3 PE: ação padrão adicional. Verdadeiro +7 PE (4º círculo e afinidade): alvos escolhidos.", "ef": []}'::jsonb),
('op:ritual:Aprimorar Físico','op','livro-basico',null,'ritual','Aprimorar Físico',2,'Sangue',1041,'{"tipo": "ritual", "circ": 2, "el": "Sangue", "pe": 3, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 ser. Duração: cena. +1 em Agilidade ou Força à escolha do alvo. Discente +3 PE (3º círculo): +2. Verdadeiro +7 PE (4º círculo e afinidade): +3.", "ef": []}'::jsonb),
('op:ritual:Descarnar','op','livro-basico',null,'ritual','Descarnar',2,'Sangue',1042,'{"tipo": "ritual", "circ": 2, "el": "Sangue", "pe": 3, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 ser. Duração: instantânea. Resistência: Fortitude parcial. 6d8 de dano (metade corte, metade Sangue) e hemorragia: no início de cada turno, Fortitude; falha = 2d8 de Sangue; 2 sucessos seguidos estancam. Passou no teste inicial: metade e sem hemorragia. Discente +3 PE (3º círculo): dano 10d8 e hemorragia 4d8. Verdadeiro +7 PE (3º círculo e afinidade): alvo você, sustentada: seus ataques corpo a corpo causam +4d8 de Sangue e hemorragia automática.", "ef": []}'::jsonb),
('op:ritual:Flagelo de Sangue','op','livro-basico',null,'ritual','Flagelo de Sangue',2,'Sangue',1043,'{"tipo": "ritual", "circ": 2, "el": "Sangue", "pe": 3, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 pessoa. Duração: cena. Resistência: Fortitude parcial. Marca com uma ordem (ex.: não ataque meus aliados). A cada rodada que o alvo desobedecer, sofre 10d6 de Sangue e fica enjoado (Fortitude reduz à metade e evita a condição). 2 sucessos seguidos apagam a marca. Discente +3 PE (3º círculo): alvo 1 ser (exceto criaturas de Sangue). Verdadeiro +7 PE (4º círculo e afinidade): como discente, duração 1 dia.", "ef": []}'::jsonb),
('op:ritual:Hemofagia','op','livro-basico',null,'ritual','Hemofagia',2,'Sangue',1044,'{"tipo": "ritual", "circ": 2, "el": "Sangue", "pe": 3, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 ser. Duração: instantânea. Resistência: Fortitude metade. 6d6 de Sangue no alvo; você recupera PV iguais à metade do dano causado. Discente +3 PE: sem resistência; ataque corpo a corpo como parte da execução, somando dano; recupera metade do total. Verdadeiro +7 PE (4º círculo): pessoal, duração cena: a cada rodada, ação padrão para tocar 1 ser: 4d6 de Sangue, recupera metade.", "ef": []}'::jsonb),
('op:ritual:Transfusão Vital','op','livro-basico',null,'ritual','Transfusão Vital',2,'Sangue',1045,'{"tipo": "ritual", "circ": 2, "el": "Sangue", "pe": 3, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 ser. Duração: instantânea. Você sofre até 30 de dano de Sangue para o alvo recuperar a mesma quantidade em PV (não deixa você abaixo de 1 PV). Discente +3 PE (3º círculo): até 50. Verdadeiro +7 PE (4º círculo): até 100.", "ef": []}'::jsonb),
('op:ritual:Proteção contra Rituais','op','livro-basico',null,'ritual','Proteção contra Rituais',2,'Medo',1046,'{"tipo": "ritual", "circ": 2, "el": "Medo", "pe": 3, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 ser. Duração: cena. Resistência a dano paranormal 5 e +5 em testes de resistência contra rituais e habilidades de criaturas paranormais. Discente +3 PE (3º círculo): até 5 seres tocados. Verdadeiro +6 PE (4º círculo): até 5 seres, resistência 10 e +10 nos testes.", "ef": []}'::jsonb),
('op:ritual:Rejeitar Névoa','op','livro-basico',null,'ritual','Rejeitar Névoa',2,'Medo',1047,'{"tipo": "ritual", "circ": 2, "el": "Medo", "pe": 3, "desc": "Execução: padrão. Alcance: curto. Alvo/área: nuvem de 6m de raio. Duração: cena. Rituais conjurados na área custam +2 PE por círculo e têm a execução aumentada em um passo. Anula Cinerária, a menos que o conjurador dela gaste ação completa por rodada para mantê-la (neutralizando os dois). Discente +2 PE: DT de resistência contra rituais feitos na área –5. Verdadeiro +5 PE: como discente; dano de rituais dentro da névoa é sempre o mínimo.", "ef": []}'::jsonb),
('op:ritual:Alterar Memória','op','livro-basico',null,'ritual','Alterar Memória',3,'Conhecimento',1048,'{"tipo": "ritual", "circ": 3, "el": "Conhecimento", "pe": 6, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 pessoa. Duração: instantânea. Resistência: Vontade anula. Altera ou apaga memórias de até 1 hora atrás (muda detalhes, não reescreve eventos). O alvo as recupera em 1d4 dias. Verdadeiro +4 PE (4º círculo): memórias de até 24 horas.", "ef": []}'::jsonb),
('op:ritual:Contato Paranormal','op','livro-basico',null,'ritual','Contato Paranormal',3,'Conhecimento',1049,'{"tipo": "ritual", "circ": 3, "el": "Conhecimento", "pe": 6, "desc": "Execução: completa. Alcance: pessoal. Alvo/área: você. Duração: 1 dia. Recebe 6d6. Em qualquer teste de perícia, gasta um, rola e soma ao resultado; ao rolar 6, a entidade toma 2 de Sanidade. Sem dados ou SAN 0, o ritual acaba. Discente +4 PE (4º círculo): d8; ao rolar 8, perde 3 SAN. Verdadeiro +9 PE (4º círculo e afinidade): d12; ao rolar 12, perde 5 SAN.", "ef": []}'::jsonb),
('op:ritual:Mergulho Mental','op','livro-basico',null,'ritual','Mergulho Mental',3,'Conhecimento',1050,'{"tipo": "ritual", "circ": 3, "el": "Conhecimento", "pe": 6, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 pessoa. Duração: sustentada. Resistência: Vontade parcial (veja texto). Você fica desprevenido. No início de cada turno seu tocando o alvo, ele faz Vontade; se falhar, responde uma pergunta de sim ou não sem poder mentir. Verdadeiro +4 PE (4º círculo): execução 1 dia, alcance ilimitado; exige cuba de ouro com água e máscara (acessório cat. II), informação e objeto pessoal ou foto do alvo.", "ef": []}'::jsonb),
('op:ritual:Vidência','op','livro-basico',null,'ritual','Vidência',3,'Conhecimento',1051,'{"tipo": "ritual", "circ": 3, "el": "Conhecimento", "pe": 6, "desc": "Execução: completa. Alcance: ilimitado. Alvo/área: 1 ser. Duração: 5 rodadas. Resistência: Vontade anula. Por superfície reflexiva, vê e ouve o alvo e o entorno (6m). O alvo faz resistência no início de cada turno dele; 2 sucessos seguidos encerram e o tornam imune por 1 semana. Precisa de informação sobre o alvo; bônus dele na resistência: quase nada sabido +10, algumas informações +5, conhece bem 0, pertence pessoal –5, parte do corpo –10.", "ef": []}'::jsonb),
('op:ritual:Convocação Instantânea','op','livro-basico',null,'ritual','Convocação Instantânea',3,'Energia',1052,'{"tipo": "ritual", "circ": 3, "el": "Energia", "pe": 6, "desc": "Execução: padrão. Alcance: ilimitado. Alvo/área: 1 objeto de até 2 espaços. Duração: instantânea. Resistência: Vontade anula. Convoca para a mão um objeto previamente marcado com o símbolo do ritual. Se estiver com outra pessoa, ela faz Vontade para negar, mas você sabe onde está. Por até 1h pode mandá-lo de volta (ação de movimento). Discente +4 PE: objeto de até 10 espaços. Verdadeiro +9 PE: 1 recipiente Médio com itens até 10 espaços, permanente: escondido no Outro Lado, convocado com ação padrão; exige miniatura (utensílio cat. II); você perde 1 PE permanentemente.", "ef": []}'::jsonb),
('op:ritual:Salto Fantasma','op','livro-basico',null,'ritual','Salto Fantasma',3,'Energia',1053,'{"tipo": "ritual", "circ": 3, "el": "Energia", "pe": 6, "desc": "Execução: padrão. Alcance: médio. Alvo/área: você. Duração: instantânea. Vira Energia e reaparece em ponto que já observou (sem precisar de linha de efeito). Não age pelo resto do turno. Sem espaço livre, surge no mais próximo. Discente +2 PE: execução reação: salta para espaço adjacente, +10 na Defesa e Reflexos contra um ataque ou efeito. Verdadeiro +4 PE: alcance longo; alvo você e até 2 seres voluntários tocados.", "ef": []}'::jsonb),
('op:ritual:Transfigurar Terra','op','livro-basico',null,'ritual','Transfigurar Terra',3,'Energia',1054,'{"tipo": "ritual", "circ": 3, "el": "Energia", "pe": 6, "desc": "Execução: padrão. Alcance: longo. Alvo/área: 9 cubos de 1,5m. Duração: instantânea. Resistência: veja texto. Escolha: Amolecer (teto ou suporte desaba: 10d6 de impacto, Reflexos metade; piso vira terreno difícil), Modelar (objetos simples até Enorme sem mecanismos; paredes dão cobertura total, RD 8 e 50 PV por 3m), Solidificar (lama ou areia vira terra ou pedra; seres agarrados, Atletismo DT do ritual). Discente +3 PE: 15 cubos. Verdadeiro +7 PE (4º círculo): afeta também todos os minerais e metais.", "ef": []}'::jsonb),
('op:ritual:Transfigurar Água','op','livro-basico',null,'ritual','Transfigurar Água',3,'Energia',1055,'{"tipo": "ritual", "circ": 3, "el": "Energia", "pe": 6, "desc": "Execução: padrão. Alcance: longo. Alvo/área: esfera de 30m de raio. Duração: cena. Resistência: veja texto. Escolha: Congelar (água vira gelo; nadadores imóveis, Atletismo DT do ritual), Derreter (gelo vira água, termina), Enchente (+4,5m de nível; ou embarcação com +6m de deslocamento), Evaporar (5d8 de Energia em seres vivos, Fortitude metade, Morte dobro; termina), Partir (–4,5m: caminho seco ou redemoinho que prende barcos, Pilotagem DT do ritual). Verdadeiro +5 PE: enchente +12m de deslocamento; evaporar 10d8.", "ef": []}'::jsonb),
('op:ritual:Poeira da Podridão','op','livro-basico',null,'ritual','Poeira da Podridão',3,'Morte',1056,'{"tipo": "ritual", "circ": 3, "el": "Morte", "pe": 6, "desc": "Execução: padrão. Alcance: médio. Alvo/área: nuvem de 6m de raio. Duração: sustentada. Resistência: Fortitude (veja texto). Ao conjurar e no início de cada turno seu, seres e objetos na área sofrem 4d8 de Morte (Fortitude metade). Quem falha não recupera PV por 1 rodada. Verdadeiro +4 PE: dano 4d8+16.", "ef": []}'::jsonb),
('op:ritual:Tentáculos de Lodo','op','livro-basico',null,'ritual','Tentáculos de Lodo',3,'Morte',1057,'{"tipo": "ritual", "circ": 3, "el": "Morte", "pe": 6, "desc": "Execução: padrão. Alcance: médio. Alvo/área: círculo de 6m de raio. Duração: cena. Ao conjurar e no início de cada turno seu, faz agarrar (Ocultismo no lugar de Luta) contra cada alvo na área; vencendo, agarra; se já agarrado, esmaga: 4d6 (metade impacto, metade Morte). Área é terreno difícil; tentáculos imunes a dano. Verdadeiro +5 PE: raio 9m e dano 6d6.", "ef": []}'::jsonb),
('op:ritual:Zerar Entropia','op','livro-basico',null,'ritual','Zerar Entropia',3,'Morte',1058,'{"tipo": "ritual", "circ": 3, "el": "Morte", "pe": 6, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 pessoa. Duração: cena. Resistência: Vontade parcial. O alvo fica paralisado (passou: lento). No início de cada turno dele, pode gastar ação completa para novo teste de Vontade e encerrar o efeito. Discente +4 PE (4º círculo): alvo 1 ser. Verdadeiro +11 PE (4º círculo e afinidade): seres escolhidos.", "ef": []}'::jsonb),
('op:ritual:Âncora Temporal','op','livro-basico',null,'ritual','Âncora Temporal',3,'Morte',1059,'{"tipo": "ritual", "circ": 3, "el": "Morte", "pe": 6, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 ser. Duração: cena. Resistência: Vontade parcial. No início de cada turno do alvo, Vontade; se falhar, ele não pode se deslocar naquele turno. 2 sucessos seguidos terminam o efeito. Verdadeiro +4 PE (4º círculo): alvo seres à sua escolha.", "ef": []}'::jsonb),
('op:ritual:Ferver Sangue','op','livro-basico',null,'ritual','Ferver Sangue',3,'Sangue',1060,'{"tipo": "ritual", "circ": 3, "el": "Sangue", "pe": 6, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 ser. Duração: sustentada. Resistência: Fortitude parcial. Ao conjurar e no início de cada turno dele, Fortitude; falha = 4d8 de Sangue e fraco; passou = metade e sem fraco. 2 sucessos seguidos terminam. Verdadeiro +4 PE (4º círculo e afinidade): seres escolhidos.", "ef": []}'::jsonb),
('op:ritual:Forma Monstruosa','op','livro-basico',null,'ritual','Forma Monstruosa',3,'Sangue',1061,'{"tipo": "ritual", "circ": 3, "el": "Sangue", "pe": 6, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: você. Duração: cena. Assume forma de criatura de Sangue: tamanho Grande, +5 em ataque e dano corpo a corpo, 30 PV temporários. Equipamento fica inacessível (bônus mantidos). Não fala nem conjura; a cada rodada deve atacar o ser mais próximo (se for aliado, Vontade DT do ritual para escolher). Discente +3 PE: imunidade a atordoamento, fadiga, sangramento, sono e veneno. Verdadeiro +9 PE (4º círculo e afinidade): bônus +10 e 50 PV temporários.", "ef": []}'::jsonb),
('op:ritual:Purgatório','op','livro-basico',null,'ritual','Purgatório',3,'Sangue',1062,'{"tipo": "ritual", "circ": 3, "el": "Sangue", "pe": 6, "desc": "Execução: padrão. Alcance: curto. Alvo/área: área de 6m de raio. Duração: sustentada. Resistência: Fortitude parcial. Poça de sangue: inimigos na área ficam vulneráveis a dano balístico, de corte, de impacto e de perfuração. Quem tenta sair sofre 6d6 de Sangue e faz Fortitude: passou, sai; falhou, perde a ação de movimento.", "ef": []}'::jsonb),
('op:ritual:Vomitar Pestes','op','livro-basico',null,'ritual','Vomitar Pestes',3,'Sangue',1063,'{"tipo": "ritual", "circ": 3, "el": "Sangue", "pe": 6, "desc": "Execução: padrão. Alcance: médio. Alvo/área: 1 enxame Grande (quadrado de 3m). Duração: sustentada. Resistência: Reflexos metade. Enxame de criaturas de Sangue surge adjacente. No fim de cada turno seu, causa 5d12 de Sangue a quem estiver no espaço dele (Reflexos metade). Ação de movimento move o enxame 12m. Discente +2 PE: quem falha no Reflexos fica agarrado (ação padrão com Acrobacia ou Atletismo para escapar). Verdadeiro +5 PE: enxame Enorme (cubo de 6m) com voo 18m.", "ef": []}'::jsonb),
('op:ritual:Dissipar Ritual','op','livro-basico',null,'ritual','Dissipar Ritual',3,'Medo',1064,'{"tipo": "ritual", "circ": 3, "el": "Medo", "pe": 6, "desc": "Execução: padrão. Alcance: médio. Alvo/área: 1 ser ou objeto, ou esfera de 3m de raio. Duração: instantânea. Teste de Ocultismo: anula rituais ativos no alvo ou na área com DT igual ou menor ao resultado (não afeta efeitos instantâneos). Em item amaldiçoado, torna-o mundano por 1 dia (o portador faz Vontade para negar).", "ef": []}'::jsonb),
('op:ritual:Controle Mental','op','livro-basico',null,'ritual','Controle Mental',4,'Conhecimento',1065,'{"tipo": "ritual", "circ": 4, "el": "Conhecimento", "pe": 10, "desc": "Execução: padrão. Alcance: médio. Alvo/área: 1 pessoa ou animal. Duração: sustentada. Resistência: Vontade parcial. O alvo obedece todos os comandos, exceto ordens suicidas. Vontade no fim de cada turno dele para se livrar; quem passa fica pasmo por 1 rodada (uma vez por cena). Discente +5 PE: até 5 pessoas ou animais. Verdadeiro +10 PE (afinidade com Conhecimento): até 10.", "ef": []}'::jsonb),
('op:ritual:Inexistir','op','livro-basico',null,'ritual','Inexistir',4,'Conhecimento',1066,'{"tipo": "ritual", "circ": 4, "el": "Conhecimento", "pe": 10, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 ser. Duração: instantânea. Resistência: Vontade parcial. 10d12+10 de Conhecimento (passou: 2d12 e debilitado por 1 rodada). Se os PV chegarem a 0, o alvo é apagado da existência. Discente +5 PE: 15d12+15 (resistido 3d12). Verdadeiro +10 PE (afinidade): 20d12+20 (resistido 4d12).", "ef": []}'::jsonb),
('op:ritual:Possessão','op','livro-basico',null,'ritual','Possessão',4,'Conhecimento',1067,'{"tipo": "ritual", "circ": 4, "el": "Conhecimento", "pe": 10, "desc": "Execução: padrão. Alcance: longo. Alvo/área: 1 pessoa viva ou morta. Duração: 1 dia. Resistência: Vontade anula. Projeta sua consciência no corpo do alvo e o controla (usa sua ficha com Agilidade, Força, Vigor e deslocamento do alvo). Se ele passar, sabe da tentativa e fica imune por 1 dia. Se um dos dois morrer, a mente sobrevivente fica presa no corpo novo. Voltar ao seu corpo é ação livre.", "ef": []}'::jsonb),
('op:ritual:Alterar Destino','op','livro-basico',null,'ritual','Alterar Destino',4,'Energia',1068,'{"tipo": "ritual", "circ": 4, "el": "Energia", "pe": 10, "desc": "Execução: reação. Alcance: pessoal. Alvo/área: você. Duração: instantânea. Vislumbra o futuro próximo: +15 em um teste de resistência ou na Defesa contra um ataque. Verdadeiro +5 PE: alcance curto, alvo um aliado à sua escolha.", "ef": []}'::jsonb),
('op:ritual:Deflagração de Energia','op','livro-basico',null,'ritual','Deflagração de Energia',4,'Energia',1069,'{"tipo": "ritual", "circ": 4, "el": "Energia", "pe": 10, "desc": "Execução: completa. Alcance: pessoal. Alvo/área: explosão de 15m de raio. Duração: instantânea. Resistência: Fortitude parcial. 3d10 x 10 de Energia em todos na área e itens tecnológicos quebram. Você não é afetado. Quem passa sofre metade e seus itens voltam após 1d4 rodadas. Verdadeiro +5 PE: afeta apenas alvos à sua escolha.", "ef": []}'::jsonb),
('op:ritual:Teletransporte','op','livro-basico',null,'ritual','Teletransporte',4,'Energia',1070,'{"tipo": "ritual", "circ": 4, "el": "Energia", "pe": 10, "desc": "Execução: padrão. Alcance: toque. Alvo/área: até 5 seres voluntários. Duração: instantânea. Leva os alvos a um lugar a até 1.000 km. Ocultismo: DT 25 (lugar que visita com frequência), 30 (já visitou uma vez), 35 (só por descrição de alguém). Falha: chega a lugar parecido (até 1d10 x 10 km errado); falha por 5 ou mais: o ritual falha e você fica atordoado por 1d4 rodadas. Verdadeiro +5 PE: qualquer local na Terra.", "ef": []}'::jsonb),
('op:ritual:Convocar o Algoz','op','livro-basico',null,'ritual','Convocar o Algoz',4,'Morte',1071,'{"tipo": "ritual", "circ": 4, "el": "Morte", "pe": 10, "desc": "Execução: padrão. Alcance: 1,5m. Alvo/área: 1 pessoa. Duração: sustentada. Resistência: Vontade parcial, Fortitude parcial. Cria o maior medo do alvo (só ele o vê com nitidez). O algoz surge adjacente a você e flutua 12m em direção à vítima no fim de cada turno seu. Em alcance curto da vítima: Vontade ou abalada. Adjacente: Fortitude; falha = 0 PV; passou = 6d6 de Morte (não reduz a menos de 1 PV). Incorpóreo e imune a dano; some se deixar o alvo morrendo ou for dissipado.", "ef": []}'::jsonb),
('op:ritual:Distorção Temporal','op','livro-basico',null,'ritual','Distorção Temporal',4,'Morte',1072,'{"tipo": "ritual", "circ": 4, "el": "Morte", "pe": 10, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: veja texto. Duração: veja texto. Cria um bolsão temporal de 3 rodadas: você age, mas não se desloca nem interage com seres e objetos. Efeitos contínuos não o afetam e o que você iniciar não afeta o entorno. Efeitos de área mais longos agem normalmente depois.", "ef": []}'::jsonb),
('op:ritual:Fim Inevitável','op','livro-basico',null,'ritual','Fim Inevitável',4,'Morte',1073,'{"tipo": "ritual", "circ": 4, "el": "Morte", "pe": 10, "desc": "Execução: completa. Alcance: extremo. Alvo/área: buraco negro de 1,5m de diâmetro. Duração: 4 rodadas. Resistência: Fortitude parcial. No início de cada um dos seus 4 turnos, todos a até 90m (você incluído) fazem Fortitude; falha = caído e puxado 30m ao vácuo. Segurar-se em objeto fixo dá +5. Quem inicia o turno tocando o vácuo sofre 100 de Morte por rodada. Discente +5 PE (afinidade): 5 rodadas; você não é afetado. Verdadeiro +10 PE (afinidade): 6 rodadas; seres escolhidos não são afetados.", "ef": []}'::jsonb),
('op:ritual:Capturar o Coração','op','livro-basico',null,'ritual','Capturar o Coração',4,'Sangue',1074,'{"tipo": "ritual", "circ": 4, "el": "Sangue", "pe": 10, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 pessoa. Duração: cena. Resistência: Vontade parcial. Paixão obsessiva por você. No início de cada turno do alvo, Vontade; falha = age para ajudá-lo da melhor forma. 2 sucessos seguidos terminam.", "ef": []}'::jsonb),
('op:ritual:Invólucro de Carne','op','livro-basico',null,'ritual','Invólucro de Carne',4,'Sangue',1075,'{"tipo": "ritual", "circ": 4, "el": "Sangue", "pe": 10, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 clone seu. Duração: cena. Cria cópia idêntica, com as mesmas estatísticas e cópia do equipamento mundano. Sem consciência (Intelecto e Presença nulos): só age por ordem (ação de movimento) ou você a controla em transe, usando os sentidos dela. Percepção (DT do ritual) revela a cópia. Desfaz-se com 0 PV ou fora do alcance.", "ef": []}'::jsonb),
('op:ritual:Vínculo de Sangue','op','livro-basico',null,'ritual','Vínculo de Sangue',4,'Sangue',1076,'{"tipo": "ritual", "circ": 4, "el": "Sangue", "pe": 10, "desc": "Execução: padrão. Alcance: curto. Alvo/área: 1 ser. Duração: cena. Resistência: Fortitude anula. Sempre que você sofre dano, o alvo faz Fortitude; falha = você sofre metade e ele a outra metade. Versão inversa: você recebe metade de todo dano que o alvo receberia. Voluntários não testam.", "ef": []}'::jsonb),
('op:ritual:Canalizar o Medo','op','livro-basico',null,'ritual','Canalizar o Medo',4,'Medo',1077,'{"tipo": "ritual", "circ": 4, "el": "Medo", "pe": 10, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 pessoa. Duração: permanente até ser descarregada. Escolha um ritual de até 3º círculo que conheça: o alvo o conjura uma vez em forma básica sem pagar PE (formas avançadas com PE próprios). Até ser usado, seus PE máximos diminuem pelo custo dele. Rituais de Medo custam Sanidade igual ao custo em PE.", "ef": []}'::jsonb),
('op:ritual:Conhecendo o Medo','op','livro-basico',null,'ritual','Conhecendo o Medo',4,'Medo',1078,'{"tipo": "ritual", "circ": 4, "el": "Medo", "pe": 10, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 pessoa. Duração: instantânea. Resistência: Vontade parcial. Falha: Sanidade do alvo vai a 0 e ele fica enlouquecendo; passou: 10d6 de dano mental e apavorado por 1 rodada. Quem enlouquece vira criatura paranormal a critério do mestre.", "ef": []}'::jsonb),
('op:ritual:Lâmina do Medo','op','livro-basico',null,'ritual','Lâmina do Medo',4,'Medo',1079,'{"tipo": "ritual", "circ": 4, "el": "Medo", "pe": 10, "desc": "Execução: padrão. Alcance: toque. Alvo/área: 1 ser. Duração: instantânea. Resistência: Fortitude parcial. Golpeia com uma fenda na Realidade: falha = PV a 0 e morrendo; passou = 10d8 de Medo (ignora resistências) e apavorado por 1 rodada. O ferimento nunca cicatriza. Aprender exige poder de trilha específico (Lâmina Paranormal).", "ef": []}'::jsonb),
('op:ritual:Medo Tangível','op','livro-basico',null,'ritual','Medo Tangível',4,'Medo',1080,'{"tipo": "ritual", "circ": 4, "el": "Medo", "pe": 10, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: você. Duração: cena. Imune a atordoado, cego, debilitado, enjoado, envenenado, exausto, fatigado, fraco, lento, ofuscado e paralisado, a doenças e venenos; sem dano extra de crítico ou ataque furtivo. Dano balístico, de corte, de impacto ou de perfuração não reduz seus PV abaixo de 1.", "ef": []}'::jsonb),
('op:ritual:Presença do Medo','op','livro-basico',null,'ritual','Presença do Medo',4,'Medo',1081,'{"tipo": "ritual", "circ": 4, "el": "Medo", "pe": 10, "desc": "Execução: padrão. Alcance: pessoal. Alvo/área: emanação de 9m de raio. Duração: sustentada. Resistência: Vontade reduz à metade. Ao conjurar e no início do turno de cada alvo na área: 5d8 de dano mental e 5d8 de Medo (Vontade metade nos dois). Quem falha fica atordoado por 1 rodada (uma vez por cena).", "ef": []}'::jsonb)
